# download
import yt_dlp

def download_captions(video_ID):
    ydl_opts = {
        'writesubtitles': True,  # Tells yt-dlp to download subtitles
        'allsubtitles': False,  # Tells yt-dlp to download all available subtitles
        'writeautomaticsub': True,  # Download automatically generated subtitles
        'subtitleslangs': ['en'],  # Specify the language of the subtitles to download
        'skip_download': True,  # Skip the actual video download, download only subtitles
        'outtmpl': 'captions',  # Output filename template
    }

    with yt_dlp.YoutubeDL(ydl_opts) as ydl:
        ydl.download([f'https://www.youtube.com/watch?v={video_ID}'])


# clean downloaded Transcription
import re
import glob
import os

def extract_time_and_text(s):
    # Regular expression pattern for time and text
    time_pattern = r'<(\d{2}:\d{2}:\d{2}\.\d{3})>'
    text_pattern = r'<c>(.*?)</c>'

    # Find all times and texts in the string
    times = re.findall(time_pattern, s) # word level start timestamps for the word sequences
    texts = re.findall(text_pattern, s) # all words in the c tag :all except the first one

    # The first text is not enclosed in <c> tags, so we need to handle it separately
    first_text = s.split('<', 1)[0].strip()

    # Combine the first text with the other texts
    texts = [first_text] + texts
    text = "".join(texts) #the text for the total segment

    formated_time = [time_to_float(time) for time in times]
    # returns the texts and times as tuple
    # this returns segment text and start time for each following word
    return text,formated_time

def time_to_float(time_string):
    h, m, s = map(float, time_string.split(':'))

    # clean rounding using string formatting
    return float("%.3f" % (h * 3600 + m * 60 + s))

def parse_vtt(text):
    # pattern = r'^(?!.*-->)[^[\]<>\:]*$'
    timing = r'.*-->.*'
    sub = r'.*<[>/]?.*'
    # sounds = r'^\[[^\]]*\]$'

    lines = text.split('\n')

    subtitles = []
    current_subtitle = {}
    for line in lines:
        if re.match(timing, line):
            # we don't need to represent empty sound segments in json like we do in vtt format
            # not all time gaps need to be accounted for in json
            if current_subtitle and current_subtitle['text'] != '':
                subtitles.append(current_subtitle)
            current_subtitle = {'start': time_to_float(line[:12]), 'end': time_to_float(line[17:29]), 'text': ''}

        elif re.match(sub, line):
            txt, word_times = extract_time_and_text(line)
            current_subtitle['text'] += txt
            current_subtitle['w_times'] = word_times

        # elif line.strip() == '' or line.strip().isalpha():
        #     continue
        # elif re.match(sounds, line):
        #     continue
            # fpr now we are ignoring sounds!!!
            #current_subtitle['text'] += line.strip()


    if current_subtitle:
        subtitles.append(current_subtitle)

    return subtitles

def clean_captions(expected_file='captions.en.vtt'):
    if not os.path.isfile(expected_file):
        # Get the current directory
        current_directory = os.getcwd()
        expected_file = glob.glob(os.path.join(current_directory, '*en*.vtt'))[0]
        if not expected_file:
            raise Exception("Subtitles not possible for this Video!")
        subtitles = parse_vtt(open(expected_file, 'r').read())
    else:
        subtitles = parse_vtt(open(expected_file, 'r').read())
    return subtitles, expected_file

import os

# push translation
from mtranslate import translate

def batch_translate(segments, src_lang="en", tr_lang="am"):
    batched_segments = []
    current_segment = ''
    rem_items = []
    for segment in segments:
        # skip over empty lines and prepare for poping
        if segment['text'] == '':
            rem_items.append(segment)
            continue
        # 4k words + 1k words from prev as context maintainance window
        if len(current_segment) + len(segment['text']) <= 5000:
            current_segment += segment['text'] + '\n'
        else:
            batched_segments.append(current_segment.strip())
            current_segment = segment['text'] + '\n'
    if current_segment:
        batched_segments.append(current_segment.strip())

    # remove empty lines
    for trash in rem_items:
        segments.remove(trash)

    translated_results = []
    for batch in batched_segments:
        # Translate the batch but ignore the first 1000 characters (the context window)
        translation = translate(batch, tr_lang, src_lang)

        # because word count accross languages are not the same: we go with segment count
        translated_results.extend(translation.split("\n"))
    try:
        assert len(translated_results) == len(segments)
        #push translation into the same dictionary
        for idx in range(len(segments)):
            segments[idx]['trans'] = translated_results[idx]
    except:
        print("something is wrong",len(translated_results),len(segments))
    return segments

