import json

def gen_sub(video_ID,language_code,path):
    print(f"Downloading subtitles for {video_ID}")

    # DOWNLOAD CAPTIONS FROM YOUTUBE
    download_captions(video_ID)

    print("getting subtitles for cleaning...")

    # CLEAN DOWNLOADED CAPTIONS
    try:
        subtitles,caption_file = clean_captions()
    except:
        print(f'Subtitle not found for {video_ID}')
        return

    print(f"Traslating subtitles for {caption_file}")

    # TRANSLATE CAPTIONS
    translated = batch_translate(segments=subtitles,tr_lang=language_code)

    # SAVE TRANSLATED CAPTIONS
    if translated:
        # SAVING AS PROVIDED SPECIFICATIONS
        with open(f"{path}/{video_ID}.json", "w",encoding='utf8') as f:
            json.dump(translated, f,ensure_ascii=False)

        print(f"Subtitles saved to '{path}/{video_ID}.json'")
        print('Want Another One, Bro Chi😁?')
